export function renderCommentPanel(groupedComments, renderCommentBox, openPage = 0, openCommentId = null) {
  // group by pageNumber
  
  // console.log('render box  Comments:', comments);
  

  // console.log('Grouped Comments:', grouped);
  const pages = Object.keys(groupedComments).sort((a, b) => Number(a) - Number(b));

  // console.log('Pages with Comments:', pages); 

  return `
    <div class="commentpanelview js-comment-panel closed">
      <div class="commentliner">
        <button id="commentlinerbt" class="toolbarButton closebt" type="button" disabled="disabled" tabindex="0" data-l10n-id="pdfjs-commentlinerbt-outline-item-button">
          <span data-l10n-id="pdfjs-commentlinerbt-outline-item-button-label"></span>
        </button>
      </div>
      <div class="commentpanelviewContent">
        <div class="title">
            <span class="text">Comments</span>`+
            // <a href="javascript:;" class="closepanel js-CommentsPanelCloseButton">
            // <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" stroke-miterlimit="2" stroke-linejoin="round" fill-rule="evenodd" clip-rule="evenodd"><path fill-rule="nonzero" d="m12.002 2.005c5.518 0 9.998 4.48 9.998 9.997 0 5.518-4.48 9.998-9.998 9.998-5.517 0-9.997-4.48-9.997-9.998 0-5.517 4.48-9.997 9.997-9.997zm0 1.5c-4.69 0-8.497 3.807-8.497 8.497s3.807 8.498 8.497 8.498 8.498-3.808 8.498-8.498-3.808-8.497-8.498-8.497zm0 7.425 2.717-2.718c.146-.146.339-.219.531-.219.404 0 .75.325.75.75 0 .193-.073.384-.219.531l-2.717 2.717 2.727 2.728c.147.147.22.339.22.531 0 .427-.349.75-.75.75-.192 0-.384-.073-.53-.219l-2.729-2.728-2.728 2.728c-.146.146-.338.219-.53.219-.401 0-.751-.323-.751-.75 0-.192.073-.384.22-.531l2.728-2.728-2.722-2.722c-.146-.147-.219-.338-.219-.531 0-.425.346-.749.75-.749.192 0 .385.073.531.219z"></path></svg>
            // </a>
        `</div>
        <div class="commentcontainer">
            <div class="nodatafound js-no-comments ${pages.length > 0 ? 'hide' : '' }">
              <div class="icon">
                <svg data-name="Layer 1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><defs><style>.cls-1{fill:#dfe2ed;}</style></defs><title>Artboard 1</title><path class="cls-1" d="M50,4.5H14A3.5,3.5,0,0,0,10.5,8V56A3.5,3.5,0,0,0,14,59.5H50A3.5,3.5,0,0,0,53.5,56V8A3.5,3.5,0,0,0,50,4.5ZM50.5,56a.5.5,0,0,1-.5.5H14a.5.5,0,0,1-.5-.5V8a.5.5,0,0,1,.5-.5H50a.5.5,0,0,1,.5.5Z"></path><circle class="cls-1" cx="20.5" cy="32" r="2.5"></circle><circle class="cls-1" cx="20.5" cy="44.3" r="2.5"></circle><circle class="cls-1" cx="20.5" cy="19.7" r="2.5"></circle><rect class="cls-1" x="25.98" y="30.26" width="20.02" height="3.49"></rect><rect class="cls-1" x="25.98" y="42.55" width="20.02" height="3.49"></rect><polygon class="cls-1" points="25.98 17.96 25.98 21.45 46 21.45 46 17.96 44 17.96 25.98 17.96"></polygon></svg>
              </div>
              No Comments Yet
            </div>
            <div class="accordion ${pages.length <= 0 ? 'hide' : '' }" id="commentAccordion">
                ${pages.map((page, index) => {
                    const open = openPage == 0 ? '' : (index == openPage -1 ? 'show' : '');
                    return `
                      <div class="accordion-item">
                        <h2 class="accordion-header">
                          <button id="accordion-button-${page}" class="accordion-button ${open ? '' : 'collapsed'}"
                                  type="button"
                                  data-bs-toggle="collapse"
                                  data-bs-target="#collapse-${page}">
                            Page ${page}
                          </button>
                        </h2>
                        <div id="collapse-${page}" class="accordion-collapse collapse ${open}" data-bs-parent="#commentAccordion">
                          <div class="accordion-body">
                            ${groupedComments[page].map(renderCommentBox).join('')}
                            <!-- Add-empty-slot button (optional) -->
                          </div>
                        </div>
                      </div>
                    `;
                  }).join('')}
              </div>
        </div>
      </div>
    </div>
  `;
}