export function renderCommentBox({ id, pageNumber, xNorm, yNorm, name, createdAt, text = "", isDraft = false , isSaved = false, isShared = false, userId,updatedAt}) {
  
  const isEditingClass =( isDraft && !isSaved) ? ' editing ' : '';
  const dateTime =  new Date(( isSaved ? updatedAt : createdAt)).toLocaleString('en-GB', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  });
  return `
    <div id="comment-${id}"
         class="commenttextbox js-comment-box js-content-to-marker ${isEditingClass}"
         data-page="${pageNumber}"
         data-comment-id="${id}"
         data-x="${xNorm}"
         data-y="${yNorm}">
      <div class="commentboxheader">
        <div class="content js-content-to-marker" data-comment-id="${id}" data-page="${pageNumber}">
          ${name ? name : 'Name Here'} - ${dateTime}
        </div>

        ${isSaved ? `
        <div class="btwrap">
          <div class="dropdown">
            <a class=" commentactionbt js-comment-options" href="#" role="button" id="dropdownMenuLink-${id}" data-bs-toggle="dropdown" aria-expanded="false">
              <button id="commentactionbtToolbarToggleButton" title="Action" class="toolbarButton actionbt " type="button" tabindex="0" data-l10n-id="pdfjs-commentaction-button" aria-expanded="false" aria-haspopup="true" aria-controls="secondaryToolbar" title="Tools" fdprocessedid="vdebwa">
                <span data-l10n-id="pdfjs-commentaction-button-label">Action</span>
              </button>
            </a>

            <ul class="dropdown-menu" aria-labelledby="dropdownMenuLink-${id}">
              <li><a class="dropdown-item" href="#" data-action="edit" data-comment-id="${id}" >Edit</a></li>
              <li><a class="dropdown-item" href="#" data-action="delete" data-comment-id="${id}" >Delete</a></li>
            </ul>
            
          </div>
        </div>
        ` : '' }
      </div>
      <div class="fieldsection">
          <textarea id="input-${id}" data-id="${id}" class="comment-input ${isSaved ? 'hide' : ''}" placeholder="Add a comment...">${text}</textarea>
          <div class="inputcontent comment-text js-content-to-marker ${isSaved ? '' : 'hide' }" data-comment-id="${id}" data-page="${pageNumber}" >${text}</div>
      </div>
      <div class="comment-actions commentpostbt ${!isSaved ? '' : 'hide' }">
          <button id="comment-save-${id}" disabled="true" data-action="post" data-comment-id="${id}" class="btn btn-primary js-comment-actions-button">Save</button>
          <button data-action="cancel" data-comment-id="${id}" class="btn btn-secondary js-comment-actions-button">Cancel</button>
        </div>
    </div>
  `;
}
