// commenting.js
import { renderCommentBox as defaultRenderCommentBox } from './templates/commenting/_comment_box.js';
import { renderCommentPanel as defaultRenderCommentPanel } from './templates/commenting/_comment_panel.js';

export class CommentingSystem {
  constructor({
    individualViewerInitContainer, // viewer init (toolbar zone etc.)
    container,                      // the viewer's page container
    adapter,                        // viewer adapter (pdf, images, etc.)
    panelParentContainer,           // static container that will hold the comment panel
    renderPanelTemplate = defaultRenderCommentPanel,
    renderCommentBoxTemplate = defaultRenderCommentBox,
    onLoad = () => {},
    onPost = async () => {},
    onDelete = async () => {},
    fetchComments = async () => {},
    onFocus = () => {},
  }) {
    this.viewerContainer = individualViewerInitContainer;
    this.container = container;

    // panel parent container is the container which will hold the comment panel (sidebar)
    this.panelParentContainer = panelParentContainer;

    // this is the comment panel inside the panelParentContainer ( panel parent container is static and always exists in DOM )
    // _initPanelVariable() will set this variable after first render of the panel
    this.panel = null;

    // instance of the custom adapter being used to interface with the viewer
    // this will hold the functions actions events specific to the viewer being used
    // thus separating the viewer specific code from the commenting system code
    this.adapter = adapter; 

    // template rendering functions ( can be customized later if needed )
    // but for now default templates are used
    // and the events are bound to the classes in the default templates
    // thus if custom templates are used the classes should be same as in default templates
    // can be improved later to make it more flexible
    this.renderPanelTemplate = renderPanelTemplate;
    this.renderCommentBoxTemplate = renderCommentBoxTemplate;

    this.onLoad = onLoad;
    this.onPost = onPost;
    this.onDelete = onDelete;
    this.onFocus = onFocus;
    this.fetchComments = fetchComments;

    this.comments = [];         // [{id,pageNumber,xNorm,yNorm,text,createdAt,updatedAt,name,userId,isDraft,isSaved}]
    window.comments = this.comments; // for easy debugging
    this.markers = new Map();   // id -> marker element

    this.active = false;        // comment mode flag
    this.hasDraft = false;      // whether a draft exists (prevents creating multiple drafts)

    this.hasFetched = false;    // whether comments have been fetched from backend

    // this.eventBus = [];         // reserved for future (custom app events)

    // this.fetchedComments = false; // whether comments have been fetched from backend 
    this.scrollToMarkerId = null; // id of comment to scroll to on next render (if any)

    // Bind viewer-level events ONCE (toolbar buttons etc.)
    this._bindInitialEvents();

    // Bind click-to-create on the viewer surface
    this._viewerCreateCommentEvent();

    // Initial render of panel (empty)
    this.renderCommentPanel();
  }

  /* 
   * Panel open/close
   */
  _togglePanel(action) {
    // action: 'open' | 'close' | undefined (toggle)
    if (!this.panel) return;
    if (action === 'open') this.panel.classList.remove('closed');
    else if (action === 'close') this.panel.classList.add('closed');
    else this.panel.classList.toggle('closed');
  }

  _initPanelVariable() {
    // comment sidebar panel element (inside panelParentContainer)
    this.panel = this.panelParentContainer.querySelector('.js-comment-panel');
  }

  /* 
   * Initial events (toolbar etc.) — bind once
   */
  _bindInitialEvents() {
    // toggle comment mode (comes from viewer toolbar)
    this.commentButton = this.viewerContainer.querySelector('.js-CommentsButton');
    this.commentButton?.addEventListener('click', () => {
      if (this.active) return; // prevent toggling off immediately when active
      this.active = !this.active;
      this.commentButton.classList.toggle('toggled', this.active);
      // use CSS for cursor; avoid inline !important in JS
      this.container.classList.toggle('marker-cursor', this.active);
    });

    // close panel button (toolbar)
    const commentPanelCloseButton = this.viewerContainer.querySelector('.js-CommentsPanelCloseButton');
    commentPanelCloseButton?.addEventListener('click', () => {
      this.active = false;
      commentPanelCloseButton?.classList.toggle('toggled', this.active);
      this.container.classList.remove('marker-cursor');
      this._togglePanel('close');
    });

    // toggle panel button (toolbar)
    const panelButton = this.viewerContainer.querySelector('.js-CommentsPanelButton');
    panelButton?.addEventListener('click', () => {
      let panelOpen = this.panel.classList.contains('closed') ? false : true;
      panelButton?.classList.toggle('toggled', !panelOpen );
      this._togglePanel();
    });
  }

  refreshMarkers() {
    // Remove all current markers from DOM
    for (const marker of this.markers.values()) marker.remove();
    this.markers.clear();

    // Place all markers again and attach events centrally
    for (const comment of this.comments) {
      const marker = this.adapter.placeMarker(comment, this.container);
      if (marker) this._markerEvents(marker, comment);
    }
  }

  placeMarkersOnPage(pageNumber) {
    const grouped = this.getGroupedComments();
    const list = grouped?.[pageNumber] || [];
    list.forEach(comment => {
      const marker = this.adapter.placeMarker(comment, this.container);
      if (marker) this._markerEvents(marker, comment);
    });
  }

  _markerEvents(marker, comment) {
    marker.addEventListener('click', (e) => {
      e.stopPropagation();
      this._togglePanel('open');
      this._focusPanelComment(comment);
      this._scrollTo({ comment });
      this._highlightComment(comment);
      this.onFocus(comment, this.adapter);
    });
    this.markers.set(Number(comment.id), marker);
  }

  _highlightComment(comment) {
    if(!comment) return;
    const elem = this.panel?.querySelector(`.js-content-to-marker[data-comment-id="${comment.id}"]`) || null;
    if (!elem || elem == 'undefined') return;
    elem.classList.add('active');
    setTimeout(() => {
      elem.classList.remove('active');
    }, 1000);
  }

  /* 
   * Scroll to comment / page
   */
  _scrollTo({ comment = null, pageNumber = null, id = null } = {}) {
    if (id && !comment) {
      comment = this.comments.find(x => x.id == id) || null;
    }
    if (pageNumber && !comment) {
      // scroll only by page
      const el = this.container.querySelector(`[data-page-number="${pageNumber}"]`);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      return;
    }
    if (!comment) return;

    // adapter for scrolling to page ( page logic in adapter )
    const page = this.container.querySelector(`[data-page-number="${comment.pageNumber}"]`);
    if(page && page.innerHTML.trim() == '' ) {
      this.adapter.scrollTo(comment, this.container);
    }

    // center on the marker after delay 
    setTimeout(() => {
      const marker = this.markers.get(comment.id);
      //console.log('Scrolling to marker:', marker, 'for comment:', comment);
      if (marker) {
        marker.scrollIntoView({ behavior: 'smooth', block: 'center' });
        marker.classList.add('highlight');
        setTimeout(() => marker.classList.remove('highlight'), 1500);
      }
    }, 100);
  }

  scrollToComment(comment) {
    this._scrollTo({ comment });
  }

  scrollToMarker(id) {
    this._scrollTo({ id });
  }

  scrollToPage(pageNumber) {
    this._scrollTo({ pageNumber });
  }

  /* 
   * Panel events (bound after each panel render)
   */
  _panelEvents() {
    if (!this.panel) return;

    this.panel.addEventListener('click', (e) => {
      const action = e.target?.dataset?.action;
      const row = e.target.closest('.js-comment-box');
      // console.log('Panel click target action row:', e.target ,  action, row);

      if(e.target?.classList.contains('js-content-to-marker')) return;

      if (!row && action !== 'close-panel') return;

      if (action === 'close-panel') {
        // remove any draft comment + marker
        const draft = this.comments.find(x => x.isDraft);
        if (draft) {
          this.deleteComment(draft.id);
        }
        this._togglePanel('close');
        return;
      }

      if (!row) return;
      
      // console.log('Panel Row dataset:', row.dataset);
      // console.log('this.comments', this.comments);
      const id = row.dataset.commentId;
      // console.log('Panel click id:', id);
      const comment = this.comments.find(x => x.id == id);
      // console.log('Panel click comment:', comment);
      if (!comment) return;

      if (action === 'post') {
        const input = this.panel.querySelector(`#input-${id}`);
        const text = input?.value ?? '';
        if (text.trim() === '') {
          alert('Comment cannot be empty');
          return;
        }
        const updated = { ...comment, text, isDraft: false, isSaved: true };
        // let external handler process save and call back into postComment
        this.onPost((saved,generatedCommentId) => this.postComment(saved,generatedCommentId), id, updated);
      } else if (action === 'edit') {
        console.log('Edit comment', id);
        // Show input and buttons, hide content for this comment row
        const input = row.querySelector('.comment-input');
        const content = row.querySelector('.comment-text');
        const postBt = row.querySelector('.comment-actions');
        console.log('Edit comment elements', { input, content, postBt });
        if (input) {
          input.classList.remove('hide');
          // Store original value for cancel
          input.dataset.originalValue = input.value;
        }
        if (postBt) postBt.classList.remove('hide');
        if (content) content.classList.add('hide');
        row.classList.add('editing');
      } else if (action === 'cancel') {
        // Restore original value and hide input/buttons, show content
        const input = row.querySelector('.comment-input');
        const content = row.querySelector('.comment-text');
        const postBt = row.querySelector('.comment-actions');
        if (input && input.dataset.originalValue !== undefined) {
          input.value = input.dataset.originalValue;
        }
        if (input) input.classList.add('hide');
        if (postBt) postBt.classList.add('hide');
        if (content) content.classList.remove('hide');

        // If it was a draft, delete the entire comment
        if (comment.isDraft && !comment.isSaved) {
          this.deleteComment(id);
        }
        row.classList.remove('editing');
      } else if (action === 'delete') {
        this.onDelete((deleteId) => this.deleteComment(deleteId), id);
      } else if (action === 'focus') {
        this._scrollTo({ comment });
        this.onFocus(comment, this.adapter);
      }
    });
  }

  /* 
   * Click-to-create comment on viewer
   */
  _viewerCreateCommentEvent() {
    this.container.addEventListener('click', (e) => {
      // Only create when in comment mode and no existing draft
      if (!this.active || this.hasDraft) return;

      const target = this.adapter.getTargetAtClick(e);
      if (!target) return;

      const newComment = {
        id: `${Date.now()}`,
        ...target,
        text: '',
        createdAt: new Date().toISOString(),
        isDraft: true,
        isSaved: false,
        name: document.getElementById('docViewerContainer')?.dataset?.userName || 'You',
        userId: document.getElementById('docViewerContainer')?.dataset?.userId || 0,
      };

      this.comments.push(newComment);

      const marker = this.adapter.placeMarker(newComment, this.container);
      if (marker) this._markerEvents(marker, newComment);

      this.renderCommentPanel();
      this._togglePanel('open');

      setTimeout(() => {
        this.checkCommentBoxEmpty();
        this._focusPanelComment(newComment);
      }, 100);

      // reset comment mode
      this.active = false;
      this.commentButton?.classList.toggle('toggled', this.active);
      this.container.classList.remove('marker-cursor');
      this.hasDraft = true;
    });
  }

  // load comments (user/file-based from backend)
  setComments(list) {
    // load comments (from backend)
    this.clear(false); // clear without re-render
    this.comments = Array.isArray(list) ? [...list] : [];
    this.refreshMarkers();
    this.renderCommentPanel();
  }

  postComment(comment, generatedCommentId) {
    // Merge the saved comment into local list
    const idx = this.comments.findIndex(x => x.id == generatedCommentId);
    console.log('IDX', idx);
    if (idx >= 0) {
      console.log('comment', this.comments[idx], 'updated with', comment);
      this.comments[idx] = { ...this.comments[idx], ...comment };
    }
    //console.log('postComment', this.comments);

    // changing marker, remove older one and create new marker
    const marker = this.container.querySelector(`.comment-marker[data-comment-id="${generatedCommentId}"]`);
    if (marker) {
      marker.dataset.commentId = comment.id;
      this.markers.delete(Number(generatedCommentId));
      this.markers.set(Number(comment.id), marker);
    }

    const commentBox = this.panel.querySelector(`#comment-${generatedCommentId}`);
    //console.log('Updating comment box', commentBox, 'with new id', comment.id);
    const allDataAttrs = commentBox?.querySelectorAll(`[data-comment-id="${generatedCommentId}"]`);
    console.log('allDataAttrs', allDataAttrs);

    allDataAttrs.forEach((el, index) => {
      console.log('allDataAttrs EACH ', el, index);
      el.setAttribute('data-comment-id', comment.id);
    });
    commentBox.id = comment.id; // update id of comment box div

    this.hasDraft = !!this.comments.find(x => x.isDraft && !x.isSaved);

    this.renderCommentPanel();
    this._togglePanel('open');

    setTimeout(() => {
      const c = this.comments[idx] || comment;
      if (c) this._focusPanelComment(c);
      this._commentBoxCommentOptionsDropdownEvent();
    }, 200);
  }

  deleteComment(id) {
    id = Number(id) || id;
    this.comments = this.comments.filter(x => x.id != id);
    const marker = this.markers.get(id);
    if (marker) marker.remove();
    this.markers.delete(id);

    this.hasDraft = !!this.comments.find(x => x.isDraft && !x.isSaved);
    
    // check page accordion , if no comments left remove it from panel
    const comment = this.panel.querySelector(`#comment-${id}`);
    const pageAccordion = comment.closest('.accordion-item');
    const commentsInPage = pageAccordion.querySelectorAll('.js-comment-box');
    if(commentsInPage && commentsInPage.length <= 1 ) {
      pageAccordion.remove();
    } else {
      comment?.remove();
    }
    this.panel.querySelector('.js-no-comments').classList.toggle('hide', this.comments.length > 0);
    // this.renderCommentPanel(); // no need to re-render entire panel
  }

  clear(rerender = true) {
    for (const marker of this.markers.values()) marker.remove();
    this.markers.clear();
    this.comments = [];
    if (rerender) this.renderCommentPanel();
  }

  /* 
   * Panel rendering & helpers
   */
  getGroupedComments() {
    const grouped = this.comments.reduce((acc, c) => {
      (acc[c.pageNumber] ||= []).push(c);
      return acc;
    }, {});
    this.groupedComments = grouped; // Save for lazy load usage
    return grouped;
  }

  renderCommentPanel() {
    this.groupedComments = this.getGroupedComments();

    // Render HTML into sidebar container
    this.panelParentContainer.innerHTML = this.renderPanelTemplate(
      this.groupedComments,
      this.renderCommentBoxTemplate
    );

    // Initialize refs & bind panel-local events
    this._initPanelVariable();
    this._panelEvents();
    this._setupLazyAccordionLoading();
    this._commentBoxCommentClickScrollEvent();
    this._commentBoxCommentOptionsDropdownEvent(500);
    this.checkCommentBoxEmpty();
  }

  _setupLazyAccordionLoading() {
    const accordion = this.panel?.querySelector('#commentAccordion');
    if (!accordion) return;

    accordion.addEventListener('shown.bs.collapse', (e) => {
      const body = e.target.querySelector('.js-comment-body');
      const page = body?.dataset.page;
      if (!body || !page) return;

      // Prevent re-render
      if (body.dataset.loaded === 'true') return;

      const comments = this.groupedComments?.[page] || [];
      body.innerHTML = comments.map(this.renderCommentBoxTemplate).join('');
      body.dataset.loaded = 'true';
    });
  }

  _commentBoxCommentClickScrollEvent() {
    //console.log('Setting up comment box click to scroll event');
    const commentBoxContainers = this.panel?.querySelectorAll('.js-content-to-marker') || [];
    //console.log('--------------------------------------------------- Found comment box containers:', commentBoxContainers);
    if (!commentBoxContainers.length) return;

    commentBoxContainers.forEach((commentBoxContainer) => {
      commentBoxContainer.addEventListener('click', (event) => {
        // event.stopPropagation();
        const target = event.target;
        //console.log('--------------------------------------------------- TARGET :', target);
        if (
          target.closest('.js-comment-options') ||
          target.closest('.dropdown-item') ||
          target.closest('.comment-input') ||
          target.closest('.js-comment-actions-button')
        ) {
          this.scrollToMarkerId = null;
          //console.log('Clicked on options/input/button, not scrolling to marker');
          return;
        }
        this.scrollToMarkerId = target?.dataset?.commentId;
        //console.log('Click on comment box, scrolling to marker id:', this.scrollToMarkerId);
        this.scrollToMarker(this.scrollToMarkerId);
      });
    });
  }

  _commentBoxCommentOptionsDropdownEvent(timeout = 200) {
    // re-init Bootstrap dropdowns after panel render
    // console.log('Initializing dropdowns after', timeout, 'ms');
    setTimeout(() => {
      const dropdownTriggers = this.panel?.querySelectorAll('.js-comment-options') || [];
      dropdownTriggers.forEach(el => {
        // console.log('Initializing dropdown for', el);
        new bootstrap.Dropdown(el);
      });
    }, timeout);
  }

  checkCommentBoxEmpty() {
    const inputs = this.panel?.querySelectorAll('.comment-input') || [];
    if (!inputs.length) return;

    inputs.forEach(input => {
      const id = input.dataset.id;
      input.addEventListener('input', () => {
        const saveButton = this.panel.querySelector(`#comment-save-${id}`);
        if (input?.value.trim() !== '') {
          if (saveButton) saveButton.disabled = false;
          this.hasDraft = true;
        } else {
          if (saveButton) saveButton.disabled = true;
          this.hasDraft = !!this.comments.find(x => x.isDraft && !x.isSaved);
        }
      });
    });
  }

  _focusPanelComment(comment) {
    setTimeout(() => {
      const accBtn = this.panel?.querySelector(`#accordion-button-${comment?.pageNumber}`);
      accBtn?.click();
      setTimeout(() => {
        const commentBox = this.panel?.querySelector(`#comment-${comment?.id}`);
        // console.log('focusing on comment box:', commentBox);
        commentBox?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        if (!comment?.isSaved) {
          const elem = this.panel?.querySelector(`#input-${comment?.id}`);
          elem?.focus();
        }
      }, 200);
    }, 200);
  }

  openAccordion(pageId) {
    const el = document.getElementById(`collapse-${pageId}`);
    if (el) {
      new bootstrap.Collapse(el, { toggle: true });
    } else {
      console.warn(`Accordion with ID collapse-${pageId} not found`);
    }
  }
}

export default CommentingSystem;