  /**
   * Setup auto-saving of annotations
   * @private
   */
  setupAnnotationAutosave() {
    // Save annotations every 30 seconds if there are changes
    const AUTO_SAVE_INTERVAL = 5000;
    
    let lastSavedData = null;
    
    const autoSave = async () => {
      if (!this.currentFileuuid) return;
      
      try {
        const currentData = await this.getUserAnnotations();
        
        // Only save if there are changes
        if (currentData && JSON.stringify(currentData) !== JSON.stringify(lastSavedData)) {
          await this.annotationService.saveAnnotations(this.currentFileuuid, currentData);
          lastSavedData = currentData;
          console.log('Annotations auto-saved successfully');
        }
      } catch (error) {
        console.error('Auto-save annotations failed:', error);
      }
    };

    // Start auto-save timer
    setInterval(autoSave, AUTO_SAVE_INTERVAL);

  }

  async initSaveAnnotations() {
    if (this.currentFileuuid) {
      try {
        const currentData = await this.getUserAnnotations();
        if (currentData && JSON.stringify(currentData) != JSON.stringify(this.annotationService.lastSavedData)) {
          let response = await this.annotationService.saveAnnotations(this.currentFileuuid, currentData);
          console.log('Annotations saved initiated successfully');
        }
      } catch (error) {
        console.error('Failed to save annotations on unload:', error);
      }
    }
  }

