  async ensureEditorLayerReady(pageView) {
    // Maximum number of attempts to wait for the editor layer
    const MAX_ATTEMPTS = 20;
    const DELAY_MS = 100;
    
    for (let i = 0; i < MAX_ATTEMPTS; i++) {
      if (pageView.annotationEditorLayer?.ready) {
        return true;
      }
      // Wait a bit before next check
      await new Promise(resolve => setTimeout(resolve, DELAY_MS));
    }
    return false;
  }

  toFloat32(item) {
    if (item instanceof Float32Array) return item;
    if (Array.isArray(item)) return new Float32Array(item.map(v => (v == null ? NaN : Number(v))));
    if (item && typeof item === 'object') {
      const keys = Object.keys(item).map(k => parseInt(k, 10)).filter(n => !Number.isNaN(n));
      if (keys.length === 0) return new Float32Array(0);
      const max = Math.max(...keys);
      const out = new Array(max + 1).fill(NaN);
      for (const k of keys) {
        const raw = item[String(k)];
        out[k] = raw == null ? NaN : Number(raw);
      }
      return new Float32Array(out);
    }
    return new Float32Array(0);
  }

