  async renderFile(fileUrl, filename, fileuuid) {
    if (!fileUrl) {
      this.handleError("No file URL provided");
      return;
    }
    fileuuid = fileuuid || '';
    this.currentFileuuid = fileuuid;
    this.setCurrentFileuuid(fileuuid);
    console.log('this.currentFileuuid', this.currentFileuuid)

    // checking & loading for saved annotations for the current fileuuid
    // as each file loads
    // if (!this.isLoadingAnnotations && this.currentFileuuid) {
    //   console.log('Checking for saved annotations on Render File');
    //   this.isLoadingAnnotations = true;
    //   await this.loadSavedAnnotations();
    //   this.isLoadingAnnotations = false; 
    // }

    console.log('Rendering file going past annotation load');

    // cleaning up previous blob url 
    if (this._previousBlobUrl) {
      URL.revokeObjectURL(this._previousBlobUrl);
      this._previousBlobUrl = null;
    }

    // try {
      // const response = await fetch(fileUrl);
      // const blob = await response.blob();
      // const contentType = response.headers.get("Content-Type") || "";
      // const ext = this.getExtensionFromContentType(contentType, fileUrl);

      // const correctedBlob = ext === 'pdf' ? new Blob([blob], { type: 'application/pdf' }) : blob;
      // const blobUrl = URL.createObjectURL(correctedBlob);

      // ----------------------------------
      const response = await fetch(fileUrl);
      const blob = await response.blob();
      const contentType = response.headers.get("Content-Type") || "";

      // // Debug what server sends
      // console.log('Server headers:', {
      //   contentType,
      //   contentDisposition: response.headers.get('Content-Disposition'),
      //   originalBlobType: blob.type
      // });

      const ext = this.getExtensionFromContentType(contentType, fileUrl);

      // Fix MIME type for PDFs
      let finalBlob = blob;
      if (ext === 'pdf' && blob.type !== 'application/pdf') {
        // console.log(`Correcting PDF MIME type from '${blob.type}' to 'application/pdf'`);
        finalBlob = new Blob([blob], { type: 'application/pdf' });
      }

      const blobUrl = URL.createObjectURL(finalBlob);
      // ----------------------------------

      this._previousBlobUrl = blobUrl;
      this._fileContentType = contentType;

      // console.log(`Rendering file: ${fileUrl}, extension: ${ext}, blobUrl: ${blobUrl}`, `\nContent-Type: ${contentType}`);
      // console.log(blob.type, blob.size);

      await this.showViewerForExtension(ext, blobUrl, fileUrl, blob, response, filename, fileuuid);

      this.onLoaded && this.onLoaded({ ext, url: fileUrl });
    // } catch (err) {
    //   this.handleError("Failed to load file: " + err);
    // }
  }

  async showViewerForExtension(ext, blobUrl, fileUrl, blob, response, filename, fileuuid) {
    const caseuuid = this.getCurrentCaseUuid();
    const annotationBaseUrl = this.getAnnotationBaseUrl();
    this.setData('anno-get', annotationBaseUrl + '/case/'+ caseuuid + '/annotations/load/' + fileuuid );
    this.setData('anno-post', annotationBaseUrl + '/case/'+ caseuuid + '/annotations/save/' + fileuuid );
    this.setData('img-anno-get', annotationBaseUrl + '/case/'+ caseuuid + '/img-annotations/load/' + fileuuid );
    this.setData('img-anno-post', annotationBaseUrl + '/case/'+ caseuuid + '/img-annotations/save/' + fileuuid );
    // Clean up previous viewers
    // if (this.videoPlayer && typeof this.videoPlayer.dispose === 'function') {
    //   this.videoPlayer.dispose();
    //   this.videoPlayer = null;
    // }

    // setting all other download buttons
    this.setAllOtherDownloadButtons(blobUrl, fileUrl, filename);

    // if (ext === 'pdf' || ext == 'txt') {
    if (ext === 'pdf') {
      this.showPdfViewer(blobUrl,fileuuid,fileUrl);
    } else if (this.isImageExtension(ext)) {
      this.showImageViewer(blobUrl);
    } else if(this.checkLaunchExcelViewer(this._fileContentType,ext)) {
      if(this.viewerOptions.useSheetJs){
        this.showXlsxViewer(blob);
      } else {
        this.showExcelViewer(fileUrl);
      }
    } else if (ext === 'docx') {
      await this.showDocxViewer(blob);
    } else if (ext === 'pptx') {
      await this.showPptxViewer(blobUrl,fileUrl);
    } else if (this.isVideoExtension(ext)) {
      this.showMediaViewer(blobUrl, ext, 'video');
    } else if (this.isAudioExtension(ext)) {
      this.showMediaViewer(blobUrl, ext, 'audio');
    } else if (this.isTxtExtension(ext)) {
      // content type of csv also is text/csv so it includes text, hence txtViewer to be checked after excel viewer
      this.showTxtViewer(response);
    } else {
      if(this.isShowFileDownload()){
        this.showDownloadContainer(fileUrl,filename);
      } else {
        this.handleError("Unsupported file type: " + ext);
      }
    }
  }

