  makeExcelViewerReadOnly(container) {
    if (!container) return;

    // Disable contenteditable on all cells
    container.querySelectorAll('td, th').forEach(cell => {
      cell.setAttribute('contenteditable', 'false');
    });

    // Disable pointer events and prevent keyboard/paste input
    container.classList.add('readonly-excel');

    // Block keyboard and paste input
    const blockInput = (e) => e.preventDefault();
    container.addEventListener('keydown', blockInput);
    container.addEventListener('paste', blockInput);
  }

