  renderFilesSelection(){
    const fileSelectionContainer = this.container.querySelector('#fileSelectionContainer');
    const fileDataObj = this. getDataJson('documents');

    if (!fileSelectionContainer || !fileDataObj) return;

    // Remove previous content
    fileSelectionContainer.innerHTML = '';


    // Iterate over keys except 'master'
    Object.keys(fileDataObj).forEach(category => {
      // skipping master as it is not a selection category (case-insensitive)
      if (category.toLowerCase() === 'master') return;
      const selectionData = fileDataObj[category];
      if (Array.isArray(selectionData) && selectionData.length > 0) {
        const selectHtml = renderSelectFilePartial(category, selectionData);
        const temp = document.createElement('div');
        temp.innerHTML = selectHtml;
        const selectNode = temp.firstElementChild;
        // Find the select element by its unique class for this category
        const selectElem = selectNode.querySelector(`select.category-${category}-select`);
        if (selectElem) {
          // register Event
          selectElem.addEventListener('change', (e) => {
            const selectedValue = e.target.value;
            if (selectedValue) {
              document.querySelectorAll('.select-categories').forEach(select => {
                if(select.id != e.target.id) select.selectedIndex = 0;
              });
              // alert(e.target.dataset['fileuuid']);
              this.renderFile(selectedValue, this.buildDownloadFilename(e.target.dataset['fileName']), e.target.dataset['fileuuid'] );
            }
          });
        }
        fileSelectionContainer.appendChild(selectNode);
      }
    });

    this.renderMasterFile();
  }

