  setDownloadEventListener(element, blobUrl, downloadFileUrl) {
    element.dataset['blobUrl'] = blobUrl;
  
    if (!element._downloadListenerAttached) {
      element._downloadListenerAttached = true;

      element.addEventListener('click', (e) => {
        const fileName = element.dataset['fileName'];
        const blobHref = element.dataset['blobUrl'];

        const temp = document.createElement('a');
        temp.href = blobHref;
        temp.download = (fileName || 'download');
        temp.style.display = 'none';
        temp.target = '_blank';

        document.body.appendChild(temp);
        temp.click();
        document.body.removeChild(temp);
      });
    }
  }

