  checkIncludes(contentType, types) {
    return types.some(type => contentType.includes(type));
  }

  getExtensionFromContentType(contentType, url) {
    const ext = this.getFileExtension(url);
    if (this.checkIncludes(contentType, ["pdf", "application/pdf"]) || ext === 'pdf') return "pdf";
    if (this.checkIncludes(contentType, ["word"])) return "docx";
    if (this.checkIncludes(contentType, ["pptx","presentation"]) || ext == "pptx")return "pptx";
    if (this.checkIncludes(contentType, ["txt","rtf","text"])) return this.getFileExtension(url) || "txt";
    if (this.checkIncludes(contentType, ["image"])) return this.getFileExtension(url) || "jpeg";
    if (this.checkIncludes(contentType, ["video"])) return this.getFileExtension(url) || 'mp4';
    if (this.checkIncludes(contentType, ["audio"])) return this.getFileExtension(url) || 'mp3';
    return ext;
  }

  observeSlidesBuilt(callback, delay = 200) {
    const container = document.querySelector('#pptxViewer');
    if (!container) return;

    let timeoutId = null;

    const observer = new MutationObserver(() => {
      if (timeoutId) clearTimeout(timeoutId);
      timeoutId = setTimeout(() => {
        observer.disconnect();
        callback();
      }, delay);
    });

    observer.observe(container, { childList: true, subtree: true });
  }

  wrapSlides() {
    const viewer = document.querySelector('#pptxViewer');
    const slides = viewer.querySelectorAll('.slide');

    slides.forEach(slide => {
      // Skip if already wrapped
      if (slide.parentElement.classList.contains('slide-wrapper')) return;

      const wrapper = document.createElement('div');
      wrapper.className = 'slide-wrapper';

      // Replace in DOM
      slide.replaceWith(wrapper);
      wrapper.appendChild(slide);
    });
  }

  scalePPTXSlides() {
    // for slide wrapper 
    const container = document.querySelector('#pptxViewer');
    const firstSlide = container.querySelector('.slide');

    if (!firstSlide) return;

    const baseWidth = parseFloat(firstSlide.style.width);
    const baseHeight = parseFloat(firstSlide.style.height);
    const containerWidth = container.clientWidth;

    const scale = Math.min((containerWidth / baseWidth), 1);

    document.querySelectorAll('#pptxViewer .slide-wrapper').forEach(wrapper => {
      const slide = wrapper.querySelector('.slide');
      slide.style.transform = `scale(${scale})`;
      slide.style.transformOrigin = 'top left';

      wrapper.style.height = `${baseHeight * scale}px`; // set wrapper height
    });
  }

