  /** annotation extension loading code start*/
  _bindAnnotationLifecycle() {
    if (this._annotationLifecycleBound) return;
    const bus = PDFViewerApplication.eventBus;

    bus.on("documentloaded", async () => {
      try {
        await this._ensureAnnotExtLoaded();
        this._destroyAnnotation();                  // to prevent duplicates
        this._annotationInstance = await this._createAnnotationInstance();
      } catch (e) {
        console.error("[annot] init failed:", e);
      }
    });

    bus.on("documentclosing", () => {
      this._destroyAnnotation();
    });

    this._annotationLifecycleBound = true;
  }

  async _createAnnotationInstance() {
    // Try common patterns exposed by annotation extensions
    if (window.PDFJSAnnotExt?.init) {
      // many libs expose an async init({ app })
      return await window.PDFJSAnnotExt.init({ app: PDFViewerApplication });
    }
    if (typeof window.PDFJSAnnotExt === "function") {
      // others export a constructor that takes the app
      return new window.PDFJSAnnotExt(PDFViewerApplication);
    }
    // Fallback: some bundles attach a default export on a namespace
    if (window.pdfjsAnnotationExtension?.default) {
      return await window.pdfjsAnnotationExtension.default(PDFViewerApplication);
    }

    console.warn("[annot] Extension loaded but no known entry point found.");
    return null;
  }

  _destroyAnnotation() {
    try {
      this._annotationInstance?.destroy?.();
    } catch (e) {
      console.warn("[annot] destroy threw:", e);
    }
    this._annotationInstance = null;
  }

  /** annotation extension loading code end */

  
