  getFileExtension(url) {
    let splitUrl = url.split('.');
    console.log('Split URL:', splitUrl);
    if (splitUrl.length < 2) return ''; // No extension found
    let ext = splitUrl.pop().toLowerCase().split('?')[0].split('#')[0];
    // fallback for no extension
    console.log('Get File extension:', ext, 'from URL:', url);
    if (!ext || ext.length > 5) return '';
    return ext;
  }

  isVideoExtension(ext) {
    return ['mp4', 'webm', 'ogv', 'ogg', 'mov', 'm4v','m3u8','mpd'].includes(ext);
  }

  isImageExtension(ext){
    return ['jpg', 'jpeg', 'png', 'gif','svg', 'bmp', 'webp'].includes(ext);
  }
  
  isTxtExtension(ext) {
    return ['txt', 'md'].includes(ext);
  }

  isAudioExtension(ext) {
    return ['mp3', 'wav', 'aac', 'flac', 'ogg', 'm4a'].includes(ext);
  }

  checkLaunchExcelViewer(mimeType,ext){
    console.log('Check Launch Excel Viewer:', mimeType, ext);
    return this.isExcelExtension(ext) || this.isExcelMimeType(mimeType);
  }

  isExcelExtension(ext){
    return ['xlsx', 'xls', 'csv', 'ods'].includes(ext);
  }

  isExcelMimeType(mimeType) {
    const type = mimeType.split(';')[0];
    const supportedMimes = [
      'application/vnd.ms-excel', // .xls
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', // .xlsx
      'text/csv',
      'application/csv',
      'application/vnd.oasis.opendocument.spreadsheet' // .ods
    ];

    return supportedMimes.includes(type);
  }

  getMimeType(ext, typeHint) {
    // typeHint: 'video' or 'audio'
    if (typeHint === 'video') {
      switch (ext) {
        case 'mp4': return 'video/mp4';
        case 'webm': return 'video/webm';
        case 'ogg': case 'ogv': return 'video/ogg';
        case 'mov': return 'video/quicktime';
        case 'm4v': return 'video/x-m4v';
      }
    } else if (typeHint === 'audio') {
      switch (ext) {
        case 'mp3': return 'audio/mp3';
        case 'wav': return 'audio/wav';
        case 'aac': return 'audio/aac';
        case 'flac': return 'audio/flac';
        case 'ogg': return 'audio/ogg';
        case 'm4a': return 'audio/mp4';
      }
    }
    return '';
  }

  isWebmVideo(url) {
    return new Promise((resolve, reject) => {
      // const url = URL.createObjectURL(file);
      const video = document.createElement('video');

      video.preload = 'metadata';
      video.src = url;

      video.onloadedmetadata = () => {
        URL.revokeObjectURL(url);
        // A duration of 0 or very close to 0 likely indicates a still image or non-video content
        const isVideo = video.duration && video.duration > 0.1;
        resolve(isVideo);
      };

      video.onerror = (e) => {
        URL.revokeObjectURL(url);
        reject(new Error("Unable to read video metadata."));
      };
    });
  }

  handleError(errMsg) {
    if (this.onError) {
      this.onError(errMsg);
    } else {
      // document.getElementById('doc-error').remove();
      console.trace(errMsg);
      // this.container.appendChild(document.createRange().createContextualFragment(`<div id='doc-error' class="docv-error">${errMsg}</div>`));
      // this.container = `<div id='doc-error' class="docv-error">${errMsg}</div>`;
      this.docLog(errMsg, true);
    }
  }

  docLog(msg, error) {
    error = error || false;
    if(this.showLog){
      if(error){
        console.error(msg);
      } else {
        console.log(msg);
      }
    }
  }
