


$(function(){
   $(".chzn-select").chosen(); 

});


function adjustChosenDirection() {
  $('.chzn-select').each(function () {
    const $select = $(this);
    const $chosen = $select.next('.chosen-container');
    if ($chosen.length == 0) {
      console.warn('Chosen container not found for select:', $select);
      return;
    }

    const rect = $chosen[0].getBoundingClientRect();
    const spaceBelow = window.innerHeight - rect.bottom;
    const spaceAbove = rect.top;

    if (spaceBelow < 210 && spaceAbove > spaceBelow) {
      $chosen.addClass('chosen-up');
    } else {
      $chosen.removeClass('chosen-up');
    }
  });
}

// Initial setup
$(".chzn-select").chosen();
adjustChosenDirection();

// Recheck on resize and scroll
$(window).on('resize scroll', adjustChosenDirection);


$(function () {
  $('[data-toggle="tooltip"]').tooltip();
});




  


