export function renderSelectFilePartial(category, selectionData) {
    const options = selectionData.map(item => `<option value="${item.url}" data-file-name="${item?.filename}" >${item.name}</option>`).join('');
    const selectTemplate = `<div class="form-grider cop-form design1">
        <div class="cop-form--container">
            <div class="dropdowns-customized chosen fs14__regular adm-u-fieldHeight48">
                <select id="category-${category}-select" data-placeholder="Select..." aria-label="Default select example" data-live-search="true" class="form-select select-categories category-${category}-select" ">
                    <option  id='${category}-disabled' selected disabled >${category}</option>
                    ${options}
                </select>
            </div>
        </div>
    </div>`;
    return selectTemplate;
}